function SweepQuestDialog:MaxClick()
    if checkInt(self.maxTimes) > self.currentNum then
        self.InputFieldNumber.text = tostring(self.maxTimes)
    else
        self.InputFieldNumber.text = tostring(self.currentNum)
    end
    self:RefreshUI()
end

function SweepQuestDialog:MinClick()
    self.currentNum = 1
    --更新显示信息
    self.InputFieldNumber.text =tostring(self.currentNum)
    self:RefreshUI()
end

function SweepQuestDialog:ReduceClick()
    if self.currentNum == 1 then
        GameUtils.Toast(localize("已经最低数量了"))
        return
    end
    self.currentNum = self.currentNum -1
    --更新显示信息
    self.InputFieldNumber.text = tostring(self.currentNum)
    self:RefreshUI()
end

function SweepQuestDialog:AddBtnClick()
    if self.currentNum >= self.maxTimes then
        GameUtils.Toast(localize("已经最大数量了"))
        return
    end
    self.currentNum = self.currentNum + 1
    --更新显示信息
    self.InputFieldNumber.text = tostring(self.currentNum)
    self:RefreshUI()
end

function SweepQuestDialog:RefreshUI()
    ---@type CommonGoodsList
    local env = self.RewardGroup.Env
    local data = self:GetConsumeGoodsData(self.currentNum)
    env:FreshBaseUI(data)
    self.InputFieldNumber.text = tostring(self.currentNum)
end

function SweepQuestDialog:SweepClick()
    if self.sweepAction then
        return
    end
    if checkInt(self.maxTimes) == 0  then
        self:ShowGoodsInsufficientTip()
        return
    end
    local questSum = self.currentNum
    if self.co  then
        cs_coroutine.stop(self.co)
        self.co = nil
    end
    self.co =  cs_coroutine.start(function()
        self.sweepAction = true
        cs_coroutine.yield_return(Yielders.ClearWaitForSeconds(0.5))
        self.sweepAction = false
    end)
    local consume = self:GetConsumeGoodsData(self.currentNum)
    --- 修正请求数据
    consume = self:FixRequestData(consume)
    GameUtils.Request(Interfaces.DailyQuestSweeping , {
        questSum = questSum ,
        consume = table.serialize(consume) ,
        questId = self.controller.Argument.parameters.questId
    }, function(request, response)
        if checkNumber(response.errCode) == 0 then
            self.sweepAction = false
            local data = response.data
            -- 当前体力
            local consumeData = {}
            for i, v in pairs(consume or {}) do
                v.num = -v.num
                consumeData[#consumeData+1] = v
            end

            for i, v in pairs(data.rewards) do
                table.insertto(consumeData , v)
            end
            local hpNum = GoodsUtils.GetThingNo(Constants.Currency.HpId)
            if data.hp and checkInt(data.hp) > 0  then
                consumeData[#consumeData+1] = {goodsId = Constants.Currency.HpId , num = data.hp - hpNum}
            end
            GoodsUtils.DrawRewards(consumeData)
            if checkInt(self.controller.Argument.parameters.freeTimesRemain) > questSum  then
                self.controller.Argument.parameters.freeTimesRemain = self.controller.Argument.parameters.freeTimesRemain - questSum
            else
                self.controller.Argument.parameters.freeTimesRemain = 0
            end
            local callback = self.controller.Argument.parameters.callback
            if callback then
                callback(self.controller.Argument.parameters.questId , questSum)
            end
            --self.currentNum = 1
            UIModule.CloseDialog(self.controller)
            UIModule.OpenDialog({ id = Constants.UITypeIds.SweepQuestRewardsDialog,
                                  parameters = data })
        end
    end)
end

function SweepQuestDialog:ShowGoodsInsufficientTip()
    local questId = self.controller.Argument.parameters.questId
    local questVo = QuestConfMgr:GetInstance():GetQuestVoById(questId)
    --- 先判断扫荡卷不足的提示语
    ---@type SweepQuestVo
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting3201,"SweepQuestVo",1)
    local num = GoodsUtils.GetThingNo(vo.num)
    if num == 0 then
        local goodsVo =  GoodsConfMgr:GetInstance():GetGoodsVoById(vo.num)
        GameUtils.Toast(localize("_name_不足", {_name_ = goodsVo.name}))
        return
    end
    -- 再判断消耗道具
    --local HpId = Constants.Currency.HpId
    local ownNum = GoodsUtils.GetThingNo(questVo.costItem)
    local costItem = checkInt(questVo.costItem)
    local costNum = checkInt(questVo.costNum)
    if ownNum < costNum then
        local vo =  GoodsConfMgr:GetInstance():GetGoodsVoById(costItem)
        GameUtils.Toast(localize("_name_不足", {_name_ = vo.name}))
        return
    end
end
--- 修正请求数据，去除体力  添加口粮单独的 playerItemId
function SweepQuestDialog:FixRequestData(consume)
    -- 最总体力
    local HpId = Constants.Currency.HpId
    local MaoKeLa = Constants.GoodsId.MaoKeLa
    for i = #consume, 1 , -1 do
        if checkInt(consume[i].goodsId) == HpId then
            table.remove(consume, i)
            break
        end
    end
    local maoKeLaNum = 0
    for i = #consume, 1 , -1 do
        if checkInt(consume[i].goodsId) == MaoKeLa  then
            maoKeLaNum = consume[i].num
            table.remove(consume, i)
            break
        end
    end
    if maoKeLaNum > 0  then
        ---@type UsableGoodComponent
        local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.UsableGoodComponent)
        local makeLaGoodsData = component:GetUsableGoodsArrayByGoodsId(MaoKeLa)
        for i = 1 , #makeLaGoodsData do
            if maoKeLaNum > 0 then
                if maoKeLaNum > makeLaGoodsData[i].num then
                    consume[#consume+1] = makeLaGoodsData[i]
                    maoKeLaNum =  maoKeLaNum - makeLaGoodsData[i].num
                else
                    local data = clone(makeLaGoodsData[i])
                    data.num = maoKeLaNum
                    consume[#consume+1] = data
                    maoKeLaNum = 0
                end
            end
        end
    end
    return consume
end

function SweepQuestDialog:BindClick()
    local SetButtonAction = SetButtonAction
    local Bind = Bind
    SetButtonAction(self.BtnClose, function()
        UIModule.CloseDialog(self.controller)
    end)
    SetButtonAction(self.BtnAdd, Bind(self, self.AddBtnClick))
    SetButtonAction(self.BtnMinus, Bind(self, self.ReduceClick))
    SetButtonAction(self.BtnMinusMin, Bind(self, self.MinClick))
    SetButtonAction(self.BtnAddMax, Bind(self, self.MaxClick))
    SetButtonAction(self.BtnAddMax, Bind(self, self.MaxClick))
    SetButtonAction(self.FontStyleButton , Bind(self,self.SweepClick))
    SetButtonAction(self.BtnClose, function()
        UIModule.CloseDialog(self.controller)
    end)
    self.InputFieldNumber.onValueChanged:AddListener(function(num)
        num = checkNumber(num)
        if num <= 1 then
            self.currentNum = 1
        elseif num >= self.maxTimes then
            self.currentNum = self.maxTimes
        else
            self.currentNum = num
        end
        self:RefreshUI()
    end)
end
--- 获取到消耗所用的道具
function SweepQuestDialog:GetConsumeGoodsData(times)
    local parameters = self.controller.Argument.parameters
    local questId = parameters.questId
    local freeTimesRemain = checkInt(parameters.freeTimesRemain)
    local consumeData = {}
    ---@type SweepQuestVo
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting3201,"SweepQuestVo",1)
    consumeData[#consumeData+1] = {goodsId = checkInt(vo.num) , num = times }
    -- 1.优先扣免费次数
    -- 免费次数足够 ， 直接return ，
    if times <= freeTimesRemain then
        return consumeData
    end
    times = times - freeTimesRemain
    local questVo = QuestConfMgr:GetInstance():GetQuestVoById(questId)
    local HpId = Constants.Currency.HpId
    local costItem = checkInt(questVo.costItem)
    local costNum = checkInt(questVo.costNum)
    if costItem ~= HpId then
        consumeData[#consumeData+1] = { goodsId = costItem , num =  times * costNum}
        return consumeData
    end

    local hpNum = GoodsUtils.GetThingNo(HpId)
    local consumeNum =  times * checkInt(questVo.costNum)
    if hpNum >= consumeNum and consumeNum > 0 then
        consumeData[#consumeData+1] = {goodsId = HpId , num = consumeNum }
        return consumeData
    end

    -- 2.优先扣除体力 ， 体力不足 ， 扣除情绪罐头
    local hpTimes = math.floor(hpNum/checkInt(questVo.costNum))
    local ownNum = 0   -- 体力剩余次数
    local consumeHp = hpTimes * questVo.costNum
    ownNum = hpNum - consumeHp
    if hpNum > 0  then
        consumeData[#consumeData+1] = {goodsId = HpId , num = hpNum }
    end

    -- 3. 扣除情绪罐头
    times = times - hpTimes
    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(Constants.GoodsId.MaoKeLa)
    if checkInt(goodsVo.effectId) == HpId then
        local num = math.ceil((questVo.costNum * times - ownNum)/ goodsVo.effectNum)
        consumeData[#consumeData+1] = {goodsId = Constants.GoodsId.MaoKeLa , num = num }
    end
    return consumeData
end
--- 获取扫荡的最大次数
function SweepQuestDialog:GetMaxNum()
    -- 1. 先判断扫到除扫荡卷之外 ， 能扫荡的最大次数
    local parameters = self.controller.Argument.parameters
    local questId = parameters.questId
    local questVo = QuestConfMgr:GetInstance():GetQuestVoById(questId)
    local HpId = Constants.Currency.HpId
    local costItem = checkInt(questVo.costItem)
    local costNum = checkInt(questVo.costNum)
    local goodsNum = GoodsUtils.GetThingNo(costItem)
    local totalTimes = 0
    local goodsTimes = math.floor(goodsNum/ costNum)
    totalTimes = totalTimes + checkInt(self.controller.Argument.parameters.freeTimesRemain)
    totalTimes = goodsTimes + totalTimes
    if costItem == HpId then
        local ownHpNum = goodsNum - costNum *goodsTimes
        -- 情绪罐头
        local MaoKeLa = Constants.GoodsId.MaoKeLa
        local numOne= GoodsUtils.GetThingNo(MaoKeLa)
        local goodsVoOne = GoodsConfMgr:GetInstance():GetGoodsVoById(MaoKeLa)
        totalTimes =  totalTimes + math.floor((checkInt(goodsVoOne.effectNum)* numOne + ownHpNum)/ costNum)
    end
    ---@type SweepQuestVo
    local sweepVo = CfUtils.GetCfVo(AutoIds.IdSetting3201,"SweepQuestVo",1)
    --2. 获取扫荡券的数量
    local sweepNum = GoodsUtils.GetThingNo(sweepVo.num)
    if sweepNum < totalTimes  then
        totalTimes = sweepNum
    end
    ---@type SweepQuestVo
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting3201,"SweepQuestVo",3)
    local maxTimes = math.min(totalTimes,vo.num )
    return maxTimes
end




